components.css:
.ds-btn-primary {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 8px 16px; border: 1px solid transparent; border-radius: var(--dq-radius, 10px);
  background: var(--dq-color-primary, #b4371c); color: #fff;
  font: 600 13px/1.4 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
  cursor: pointer;
  transition: background-color 160ms cubic-bezier(0.2,0.7,0.3,1), opacity 160ms;
}
.ds-btn-primary:hover { background: color-mix(in srgb, var(--dq-color-primary, #b4371c) 88%, #000); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--dq-color-focus, #e28663); outline-offset: 2px; }
.ds-btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }

.ds-btn-secondary {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 8px 16px; border: 1px solid var(--dq-color-border, #e1e4e8); border-radius: var(--dq-radius, 10px);
  background: var(--ts-surface, #fff); color: var(--dq-color-fg, #14161a);
  font: 600 13px/1.4 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
  cursor: pointer; transition: background-color 160ms;
}
.ds-btn-secondary:hover { background: var(--ts-surface-3, #e8ebef); }
.ds-btn-secondary:focus-visible { outline: 2px solid var(--dq-color-focus, #e28663); outline-offset: 2px; }

.ds-input {
  width: 100%; padding: 9px 12px;
  border: 1px solid var(--dq-color-border, #e1e4e8); border-radius: var(--dq-radius, 10px);
  background: var(--ts-surface, #fff); color: var(--dq-color-fg, #14161a);
  font: 400 15px/1.55 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
  transition: border-color 160ms, box-shadow 160ms;
}
.ds-input::placeholder { color: var(--dq-color-muted, #5b6270); }
.ds-input:focus-visible {
  outline: none; border-color: var(--dq-color-primary, #b4371c);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--dq-color-primary, #b4371c) 35%, transparent);
}

.ds-nav-item {
  display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 9px 12px; border: 1px solid transparent; border-radius: var(--dq-radius, 10px);
  background: transparent; color: var(--dq-color-muted, #5b6270);
  font: 550 13px/1.4 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
  text-align: left; cursor: pointer; transition: background-color 160ms, color 160ms;
}
.ds-nav-item:hover { background: var(--ts-surface-3, #e8ebef); color: var(--dq-color-fg, #14161a); }
.ds-nav-item[aria-current="page"] {
  background: color-mix(in srgb, var(--dq-color-primary, #b4371c) 9%, transparent);
  border-color: color-mix(in srgb, var(--dq-color-primary, #b4371c) 22%, transparent);
  color: var(--dq-color-primary, #b4371c); font-weight: 650;
}
.ds-nav-text { display: flex; flex-direction: column; min-width: 0; }
.ds-nav-desc { color: var(--dq-color-muted, #5b6270); font-size: 11px; font-weight: 450; }

.ds-badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 2px 8px; border: 1px solid var(--dq-color-border, #e1e4e8); border-radius: 999px;
  background: var(--ts-surface-2, #f1f3f5); color: var(--dq-color-muted, #5b6270);
  font: 600 11.5px/1.6 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif; white-space: nowrap;
}
.ds-badge--primary {
  border-color: color-mix(in srgb, var(--dq-color-primary, #b4371c) 30%, transparent);
  background: color-mix(in srgb, var(--dq-color-primary, #b4371c) 9%, transparent);
  color: var(--dq-color-primary, #b4371c);
}

.ds-kpi {
  display: flex; flex-direction: column; gap: 2px;
  padding: 16px; border: 1px solid var(--dq-color-border, #e1e4e8);
  border-radius: 14px; background: var(--ts-surface, #fff);
  box-shadow: 0 1px 2px rgb(15 23 42 / 6%);
  font-family: Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
}
.ds-kpi-label { color: var(--dq-color-muted, #5b6270); font-size: 11.5px; font-weight: 600; letter-spacing: 0.04em; text-transform: uppercase; }
.ds-kpi-value { color: var(--dq-color-fg, #14161a); font-size: 23px; font-weight: 700; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; line-height: 1.2; }
.ds-kpi-hint { color: var(--dq-color-muted, #5b6270); font-size: 11.5px; }

.ds-bubble {
  max-width: 78%; padding: 10px 14px;
  border: 1px solid var(--dq-color-border, #e1e4e8); border-radius: 14px 14px 14px 4px;
  background: var(--ts-surface-2, #f1f3f5); color: var(--dq-color-fg, #14161a);
  font: 400 15px/1.55 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
}
.ds-bubble--user {
  margin-left: auto; border-color: transparent; border-radius: 14px 14px 4px 14px;
  background: var(--dq-color-primary, #b4371c); color: #fff;
}
.ds-bubble-meta { display: flex; gap: 8px; margin-bottom: 4px; color: var(--dq-color-muted, #5b6270); font-size: 11px; }
.ds-bubble--user .ds-bubble-meta { color: rgb(255 255 255 / 78%); justify-content: flex-end; }

.ds-palette {
  width: 560px; max-width: 100%; overflow: hidden;
  border: 1px solid var(--dq-color-border, #e1e4e8); border-radius: 16px;
  background: var(--ts-surface, #fff);
  box-shadow: 0 24px 64px -24px rgb(15 23 42 / 28%), 0 2px 8px rgb(15 23 42 / 6%);
  font-family: Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif;
}
.ds-palette-input {
  width: 100%; padding: 16px 20px; border: 0; border-bottom: 1px solid var(--dq-color-border, #e1e4e8);
  background: transparent; color: var(--dq-color-fg, #14161a);
  font: 400 16px/1.5 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif; outline: none;
}
.ds-palette-group { padding: 8px 12px 4px; color: var(--dq-color-muted, #5b6270); font-size: 10.9px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; }
.ds-palette-item {
  display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 12px;
  border: 0; border-radius: 10px; background: transparent; color: var(--dq-color-fg, #14161a);
  font: 400 13px/1.4 Be Vietnam Pro, ui-sans-serif, system-ui, sans-serif; text-align: left; cursor: pointer;
}
.ds-palette-item:hover, .ds-palette-item[data-active="true"] {
  background: color-mix(in srgb, var(--dq-color-primary, #b4371c) 9%, transparent);
  color: var(--dq-color-primary, #b4371c);
}
